// === Tab: main ===
// let int PARTICLE_AMOUNT = 500;
let MAX_SPEED = 3;
let RESET_CHANCE = 0.95;

// let VISUAL
let ALPHA = 50;
let DIAMETER = 8;
let RED_MIN = 25;
let RED_MAX = 50;
let GREEN_MIN = 100;
let GREEN_MAX = 200;
let BLUE_MIN = 50;
let BLUE_MAX = 150;

// let FIELD
let COLUMNS = 64;
let ROWS = 64;
let INCREMENTS = 0.75;
let ANGLE_SCALE = TAU * sqrt(13);
let FORCE_MAGNITUDE = 2;

let forceField;
let particles;

function setup() {
	createCanvas(640, 640);
	background(0);

	forceField = new ForceField(ROWS, COLUMNS, INCREMENTS, ANGLE_SCALE);
	particles = new Array(0);
	for (i = 0; i < PARTICLE_AMOUNT; i++) {
		particles[i] = new Particle(MAX_SPEED, ALPHA, DIAMETER);
		particles[i].setColors(RED_MIN, RED_MAX, GREEN_MIN, GREEN_MAX, BLUE_MIN, BLUE_MAX);
	}
}

function draw() {
	//forceField.update();
	fill(0, 5);
	noStroke();
	rect(0, 0, width, height);
	for (let particle of particles) {
		let force = forceField.getForce(particle.getPos());
		force.setMag(FORCE_MAGNITUDE);
		particle.addForce(force);
		particle.update();
		particle.draw();
		if (RESET_CHANCE < random())
			particle.reset();
	}
}

// === Tab: particle ===
class Particle {
	vel, acl, pos;
	maxSpeed, alpha, diameter;
	maxR, minR, maxG, minG, maxB, minB;
	c;

	constructor(maxSpeed, alpha, diameter) {
		this.maxSpeed = maxSpeed;
		this.alpha = alpha;
		this.diameter = diameter;
		reset();
	}

	function addForce(force) {
		acl.add(force);
	}

	function update() {
		vel.add(acl);
		vel.limit(maxSpeed);
		pos.add(vel);
		acl.mult(0);
		wrapEdges();
	}

	function draw() {
		stroke(c, alpha);
		strokeWeight(diameter);
		point(pos.x, pos.y);
	}

	function wrapEdges() {
		if (pos.x < 0) reset();
		if (pos.x > width) reset();
		if (pos.y < 0) reset();
		if (pos.y > height) reset();
	}

	getPos() {
		return pos;
	}

	function reset() {
		vel = new PVector();
		acl = new PVector();
		pos = new PVector(random(width), random(height));
		let cPos = new PVector(pos.x - width / 2, pos.y - height / 2);
		cPos.rotate(TAU / 4);
		c = getColor(cPos.heading());
	}

	function setColors(maxR, minR, maxG, minG, maxB, minB) {
		this.maxR = maxR;
		this.minR = minR;
		this.maxG = maxG;
		this.minG = minG;
		this.maxB = maxB;
		this.minB = minB;
	}
}

// === Tab: forceField ===
class ForceField {
	row, col;
	inc, angleScale;
	vectors;
	nullVector;

	constructor(row, col, inc, angleScale) {
		this.row = row;
		this.col = col;
		this.inc = inc;
		this.angleScale = angleScale;
		this.vectors = new Array(0);
		this.nullVector = new PVector(0, 0);
		update();
	}

	function update() {
		for (y = 0; y < row; y++) {
      for (x = 0; x < col; x++) {
				let xoff = x - col / 2;
				let yoff = y - row / 2;
				let v = new PVector(xoff, yoff);
				v.rotate(TAU / 4);
        vectors[x + y * col] = v;
			}
		}
	}

	getForce(pos) {
		let x = floor(pos.x * col / width);
		let y = floor(pos.y * row / height);
		if (x < 0 || x >= row || y < 0 || y >= col)
			return nullVector;
		return vectors[y * col + x];
	}
}

// === Tab: color ===
let colors = [
	color(211, 47, 47),
	color(243, 156, 18),
	color(244, 208, 63),
	color(46, 204, 113),
	color(52, 152, 219),
	color(155, 89, 182)
];

function getColor(angle) {
	if (angle < 0)
		angle += TAU;
	let percent = angle / TAU;
	let rangeAmount = colors.length();
	let index = floor(percent * rangeAmount);
	let firstColor = colors[index];
	let secondColor = colors[index + 1 < rangeAmount ? index + 1 : 0];
	let colorPercent = rangeAmount * percent - index;

	let red = (1 - colorPercent) * (firstColor >> 16 & 0xFF) + colorPercent * (secondColor >> 16 & 0xFF);
	let green = (1 - colorPercent) * (firstColor >> 8 & 0xFF) + colorPercent * (secondColor >> 8 & 0xFF);
	let blue = (1 - colorPercent) * (firstColor & 0xFF) + colorPercent * (secondColor & 0xFF);
	return color(red, green, blue);
}

